data.value:
.container {
  width: 270px;
  border: 1px solid #ccc;
  /*background-color: rgb( 240 , 226 , 203 );*/



  border-radius: 8px;
  padding: 2px;
  font-family: sans-serif;

}

.top-section {
  display: flex;

}

.text-column {
  display: flex;
  flex-direction: column;


}

.text-box-num {
	width: 115px;


  background-color:rgba(80, 230, 150, 0.4);
  height: 30px;
  /*padding: 12px;*/
  padding-top: 4px;
  padding-bottom: -8px;
  margin-bottom: 1px;
  text-align: center;
  border-radius: 6px;
  border: 1px solid #ddd;
  font-family: 'Samim FD';
  font-weight: bold;
  font-size: 12px;

}
.text-box {
	width: 90px;
	height: 78px;
  	background-color: #f5f5f6;
 	 margin-bottom: 1px;
 	 padding: 12px;
	text-align: center;
	  border-radius: 6px;
	  border: 1px solid #ddd;
	  font-family: 'Samim FD';
 	 font-weight: bold;
	 font-size: 12px;

}
.text-box-gener {
	 /*word-wrap: break-word;*/
  overflow-wrap: break-word;


	width: 90px;
	height: 78px;
  	background-color: #f5f5f6;

 	 padding: 12px;
	text-align: right;
	  border-radius: 6px;
	  border: 1px solid #ddd;
	  font-family: 'Samim FD';
 	 font-weight: bold;
	 font-size: 12px;

}
.image-box {
  width: 145px;
  height: 190px;
  margin-left: 4px;
  background-color: #e0e0e0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  border-radius: 8px;
  border: 1px solid #bbb;
}

.bottom-text {
	white-space: pre-line;

  margin-top: 6px;

  background-color:rgb( 174 , 247 , 94 );
  color: rgb( 32 , 64 , 140 );
  padding: 8px;
  text-align: center;
  border-radius: 4px;
  border: 1px solid #ddd;
    font-family: 'Samim FD';
  font-weight: bold;
  font-size: 12px;
}
.bottom-text-no-video {
  white-space: pre-line;
  margin-top: 6px;  
  background-color:rgb( 255, 80, 50);
  color: rgb( 102 , 255, 1);
  padding: 8px;
  text-align: right;
  border-radius: 4px;
  border: 1px solid #ddd;
  font-family: 'Samim FD';
  font-weight: bold;
  font-size: 12px;

}
/*Horizontally Centered Text*/

.style {
	text-align: center;
}

/*Row with 3 Elements (Fixed/Auto Width)*/
.text-anim {
	width: 115px;


  background-color:rgba(180, 30, 150, 0.9);
  height: 30px;
  /*padding: 12px;*/
  padding-top: 4px;
  padding-bottom:-8px;
  margin-bottom: 1px;
  margin-left: 19px;
  text-align: center;
  border-radius: 10px;
  border: 1px solid #ddd;
  font-family: 'Samim FD';
  font-weight: bold;
  font-size: 13px;
  color: rgb(200, 220, 100);

}
.container0 {
	display: flex;
	height: 20px;
}
.first-element {
	background-color: Red;
	width: 150px;
}
.second-element {
	background-color: Green;
	width: auto;
}
.third-element {
	background-color: Blue;
	width: 150px;
}

/*Column with 3 Elements (Proportional Height)*/

.container1 {
	width: 100%;
	height: 100%;
}
.first-element0 {
	background-color: Transparent;
	height: 85%;
}
.second-element0 {
	background-color: Transparent;
	height: 15%;
}
